/** تهيئة كأس الـ Lottie جوه الحاوية المعطاة. بترجع كائن الأنيميشن لو
 *  نجحت، أو null لو المكتبة مش متاحة/فشلت - في الحالة دي بنظهر الكأس
 *  الاحتياطي (SVG/CSS) بدالها فوراً عشان السلايد الأخيرة تفضل شغالة
 *  دايماً مهما حصل للشبكة (نفس فلسفة باقي onboarding.js) */
function initTrophyLottie(container, fallbackEl) {
    function showFallback() {
        if (container) container.style.display = 'none';
        if (fallbackEl) fallbackEl.classList.add('onb-trophy-fallback-active');
    }

    if (!container || !window.lottie) {
        showFallback();
        return null;
    }

    try {
        const anim = window.lottie.loadAnimation({
            container,
            renderer: 'svg',
            loop: false,
            autoplay: false,
            animationData: TROPHY_LOTTIE_DATA,
        });
        anim.addEventListener('data_failed', showFallback);
        return anim;
    } catch (err) {
        // أي خطأ غير متوقع من lottie-web (نسخة غير متوافقة، بيانات
        // تالفة، ...إلخ) - منمنعش السلايد من الشغل، نرجع للاحتياطي
        showFallback();
        return null;
    }
}

