/** تهيئة أنيميشن الماشي جوه الحاوية المعطاة - لوب مستمر (loop:true)
   لأنه أيقونة خلفية دايمة الحركة، عكس الكأس اللي بيشتغل مرة واحدة
   بس لحظة الدخول. نفس منطق initTrophyLottie() تماماً في التعامل مع
   الفشل */
function initWalkLottie(container, fallbackEl) {
    function showFallback() {
        if (container) container.style.display = 'none';
        if (fallbackEl) fallbackEl.classList.add('onb-walk-fallback-active');
    }

    if (!container || !window.lottie) {
        showFallback();
        return null;
    }

    try {
        const anim = window.lottie.loadAnimation({
            container,
            renderer: 'svg',
            loop: true,
            autoplay: true,
            animationData: WALK_LOTTIE_DATA,
            // الكانفاس الأصلي بتاع الملف (1350×1600) فيه هوامش فاضية
            // كبيرة حوالين الشخصية (خصوصاً يمين/شمال)، فلو سبناها على
            // preserveAspectRatio الافتراضي (meet) الشخصية بتبان صغيرة
            // جوه المربع. "xMidYMid slice" بيكبّر لحد ما يملأ المربع
            // بالكامل (زي object-fit: cover)، والزيادة اللي بتفيض بنعمل
            // لها قص عن طريق overflow:hidden على .onb-walk-lottie تحت -
            // اتفحصت يدوياً على كل فريمات دورة المشي ومفيش أي قطع في
            // الراس أو الرجل عند الحجم ده
            rendererSettings: {
                preserveAspectRatio: 'xMidYMid slice',
            },
        });
        anim.addEventListener('data_failed', showFallback);
        return anim;
    } catch (err) {
        showFallback();
        return null;
    }
}

