/** تهيئة أنيميشن علامات الاستفهام جوه الحاوية المعطاة - لوب مستمر
 *  (loop:true) زي initWalkLottie بالظبط، عشان تفضل الأيقونة حيّة طول
 *  ما السلايد ظاهر - نفس منطق التعامل مع الفشل في باقي الدوال */
function initQuizLottie(container, fallbackEl) {
    function showFallback() {
        if (container) container.style.display = 'none';
        if (fallbackEl) fallbackEl.classList.add('onb-quiz-fallback-active');
    }

    if (!container || !window.lottie) {
        showFallback();
        return null;
    }

    try {
        const anim = window.lottie.loadAnimation({
            container,
            renderer: 'svg',
            loop: true,
            autoplay: true,
            animationData: QUIZ_LOTTIE_DATA,
        });
        anim.addEventListener('data_failed', showFallback);
        return anim;
    } catch (err) {
        showFallback();
        return null;
    }
}

