/** تهيئة أنيميشن الكأس/المنصة جوه الحاوية المعطاة - لوب مستمر
   (loop:true) زي initLocationLottie بالظبط، عشان تفضل الأيقونة حيّة
   طول ما السلايد ظاهر */
function initRankLottie(container, fallbackEl) {
    function showFallback() {
        if (container) container.style.display = 'none';
        if (fallbackEl) fallbackEl.classList.add('onb-rank-fallback-active');
    }

    if (!container || !window.lottie) {
        showFallback();
        return null;
    }

    try {
        const anim = window.lottie.loadAnimation({
            container,
            renderer: 'svg',
            loop: true,
            autoplay: true,
            animationData: RANK_LOTTIE_DATA,
        });
        anim.addEventListener('data_failed', showFallback);
        return anim;
    } catch (err) {
        showFallback();
        return null;
    }
}

