/** تهيئة أنيميشن عملة النقاط جوه الحاوية المعطاة - لوب مستمر
   (loop:true) زي initRankLottie بالظبط، عشان تفضل الأيقونة حيّة طول
   ما السلايد ظاهر */
function initPointsLottie(container, fallbackEl) {
    function showFallback() {
        if (container) container.style.display = 'none';
        if (fallbackEl) fallbackEl.classList.add('onb-points-fallback-active');
    }

    if (!container || !window.lottie) {
        showFallback();
        return null;
    }

    try {
        const anim = window.lottie.loadAnimation({
            container,
            renderer: 'svg',
            loop: true,
            autoplay: true,
            animationData: POINTS_LOTTIE_DATA,
        });
        anim.addEventListener('data_failed', showFallback);
        return anim;
    } catch (err) {
        showFallback();
        return null;
    }
}

