/** تهيئة أنيميشن الكتابة جوه الحاوية المعطاة - لوب مستمر (loop:true)
   زي initPointsLottie بالظبط، عشان تفضل الأيقونة حيّة طول ما السلايد
   ظاهر */
function initWritingLottie(container, fallbackEl) {
    function showFallback() {
        if (container) container.style.display = 'none';
        if (fallbackEl) fallbackEl.classList.add('onb-writing-fallback-active');
    }

    if (!container || !window.lottie) {
        showFallback();
        return null;
    }

    try {
        const anim = window.lottie.loadAnimation({
            container,
            renderer: 'svg',
            loop: true,
            autoplay: true,
            animationData: WRITING_LOTTIE_DATA,
        });
        anim.addEventListener('data_failed', showFallback);
        return anim;
    } catch (err) {
        showFallback();
        return null;
    }
}

/** قراءة/حفظ حالة "شاف الـ Onboarding قبل كده" - بهدوء زي theme.js */
/* ------------------------------------------------------------------
   0ب) بوابة الموقع الجغرافي قبل "إنشاء حساب جديد" (مش قبل تسجيل
   الدخول - عضو موجود بالفعل وعنده استثناء يدوي (is_verified_override)
   ممكن يكون مسافر مؤقتاً، فمينفعش نمنعه من الدخول بنفس القيد ده).
   مشتركة بين initOnboarding() و showAuthGate() تحت عشان مانكررش
   منطق الفحص نفسه في مكانين (واجهة العرض لسه بتتكرر، اتساقاً مع
   نفس أسلوب باقي الملف في تكرار onSignupClick/revealAuthForm..إلخ
   بين الدالتين).
   ------------------------------------------------------------------ */

/**
 * يشغّل فحص الموقع الجغرافي (GPS + مسافة، من غير أي كتابة في قاعدة
 * البيانات لأن معندناش userId لسه) ويرجع قرار واضح مع رسالة عربية
 * جاهزة للعرض في حالة الرفض.
 *
 * @returns {Promise<{ allowed: boolean, message: string }>}
 */
async function evaluateSignupLocationGate() {
    try {
        const { isInsideBounds } = await checkLocationForSignup();

        if (isInsideBounds) {
            return { allowed: true, message: '' };
        }

        return {
            allowed: false,
            message: 'التطبيق ده مخصص حصريًا لأهالي قرية نزلة عبيد. موقعك الحالي طلع برّه النطاق المسموح بيه، فمش هينفع تعملي حساب جديد من هنا. لو إنت فعلاً من أهالي القرية ومسافر دلوقتي، كلّمي الدعم الفني للمغتربين.',
        };
    } catch (error) {
        // فشل تحديد الموقع (رفض إذن، Timeout، GPS مش متاح..إلخ) - نفس
        // فلسفة Fail-Safe المستخدمة في initGeofencingGuard (geofence.js):
        // منقدرش نأكد إن المستخدم جوه النطاق، فبنمنع التسجيل احترازيًا
        const isLocationError = error instanceof GeofenceLocationError;

        return {
            allowed: false,
            message: isLocationError
                ? error.message
                : 'تعذّر التحقق من موقعك الجغرافي حاليًا. جرّبي تاني كمان شوية.',
        };
    }
}

/**
 * فلاج بسيط: true طول ما initOnboarding() (رحلة السلايدات الأولى) شغالة
 * فعليًا وشاشتها ظاهرة على الشاشة. الغرض منه الوحيد: حماية showAuthGate()
 * تحت من إنها تتنافس مع initOnboarding() على نفس عناصر الـ DOM (وأشهرها
 * #onbGuestBrowseBtn).
 *
 * (إصلاح - باج حقيقي): حدث 'SIGNED_OUT' من Supabase (auth.js:
 * listenToAuthStateChanges) بيتطلق تلقائيًا حتى مع أول فتحة للتطبيق لأي
 * زائر جديد ملوش جلسة أصلاً - مش بس بعد تسجيل خروج حقيقي زي ما اسمه
 * موحي - وده بينادي showAuthGate(). initOnboarding() مبتحطش كلاس
 * onb-gate-active على العنصر (الكلاس ده خاص بحارس إعادة الدخول بتاع
 * showAuthGate() بس)، فمن غير الفلاج ده، showAuthGate() كانت بتكمّل
 * عادي بالتوازي مع initOnboarding() وتضيف مستمع ضغط *تاني* على نفس
 * الزرار (زي #onbGuestBrowseBtn)، وتتلاعب في نفس عناصر الـ DOM (إخفاء/
 * إظهار السلايدات، صفحة الدخول..إلخ) بشكل منفصل تمامًا. بمجرد ما
 * المستخدم يضغط أي زرار، المستمعين الاتنين كانوا بيتنفذوا مع بعض
 * ويتصادموا على نفس العناصر - وده اللي كان بيسيب الشاشة "واقفة" من
 * غير أي رد فعل حقيقي للضغط، لحد ما Refresh يعيد تحميل الصفحة ويدّي
 * showAuthGate() فرصة تشتغل لوحدها من غير initOnboarding() تزاحمها
 * (لأن hasSeenOnboarding() كانت أصلاً false برضه، فمكانش السبب).
 */
let firstRunOnboardingActive = false;

function hasSeenOnboarding() {
    try {
        return localStorage.getItem(STORAGE_KEY) === '1';
    } catch (err) {
        return false;
    }
}

function markOnboardingSeen() {
    try {
        localStorage.setItem(STORAGE_KEY, '1');
    } catch (err) {
        // فشل الوصول لـ localStorage (وضع تصفح خفي مثلاً) - مش لازم نوقف التطبيق
    }
}

/* ------------------------------------------------------------------
   1) الأصوات واللمسات (Haptics) - نفس فكرة playSound بتاعة app.js
   لكن نسخة محلية صغيرة عشان onboarding.js يفضل مستقل ومايعملش
   Import دائري مع app.js (اللي هو أصلاً بيستورد onboarding.js)
   ------------------------------------------------------------------ */
/**
 * كانت بتشغّل نغمة قصيرة عبر Web Audio API مع كل "تيك" في الأونبوردينج -
 * اتلغت بناءً على طلب صريح (مفيش أي أصوات في التطبيق خالص دلوقتي).
 * سايبين الاهتزاز (navigator.vibrate) شغال زي ما هو لأنه Haptics مش صوت.
 */
function playHapticTick() {
    if ('vibrate' in navigator) navigator.vibrate(15);
}

/* ------------------------------------------------------------------
   2) كونفيتي بسيط لحظة الوصول لسلايد "البداية" الأخير - نسخة محلية
   خفيفة بنفس تقنية triggerConfetti() في app.js (Canvas خام من غير
   مكتبات)، بس بألوان ذهبية تناسب لحظة الكأس تحديداً
   ------------------------------------------------------------------ */
function burstGoldConfetti() {
    const canvas = document.getElementById('confettiCanvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    const originY = canvas.height * 0.42;
    const colors = ['#D4AF37', '#F2D77E', '#FFF6D1', '#B8942A'];
    const pieces = [];

    for (let i = 0; i < 60; i++) {
        pieces.push({
            x: canvas.width / 2,
            y: originY,
            vx: (Math.random() - 0.5) * 11,
            vy: (Math.random() - 0.9) * 13,
            size: Math.random() * 7 + 3,
            color: colors[Math.floor(Math.random() * colors.length)],
            rotation: Math.random() * 360,
            rotSpeed: (Math.random() - 0.5) * 9,
        });
    }

    let opacity = 1;
    function animate() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        pieces.forEach((p) => {
            p.x += p.vx;
            p.y += p.vy;
            p.vy += 0.3;
            p.rotation += p.rotSpeed;

            ctx.save();
            ctx.translate(p.x, p.y);
            ctx.rotate((p.rotation * Math.PI) / 180);
            ctx.fillStyle = p.color;
            ctx.globalAlpha = opacity;
            ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
            ctx.restore();
        });

        opacity -= 0.016;
        if (opacity > 0) {
            requestAnimationFrame(animate);
        } else {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
        }
    }
    animate();
}

/* ------------------------------------------------------------------
   3) نقطة الدخول الرئيسية
   ------------------------------------------------------------------
   بترجع Promise بتتحل بـ 'signup' أو 'login' لو المستخدم اختار
   طريقة دخول من آخر سلايد، أو null لو (نظرياً) اتقفلت الشاشة من
   غير اختيار. js/app.js هو المسؤول عن فتح authModal الفعلي بالوضع
   المناسب بعد ما يستلم القيمة دي.
   ------------------------------------------------------------------ */
export function initOnboarding() {
    return new Promise((resolve) => {
        if (hasSeenOnboarding()) {
            resolve(null);
            return;
        }

        const overlay = document.getElementById('onboardingOverlay');
        if (!overlay) {
            // العنصر مش موجود في الصفحة لأي سبب - منمنعش التطبيق من الشغل
            resolve(null);
            return;
        }

        overlay.classList.remove('hidden');
        // (إصلاح): نرفع الفلاج فور ما شاشة الترحيب تبقى ظاهرة فعليًا -
        // شوف تعليق firstRunOnboardingActive فوق لسبب وجوده
        firstRunOnboardingActive = true;

        // (إصلاح - باج حقيقي): #onboardingOverlay عنصر "fixed" بيتعرض
        // فوق واجهة التطبيق الكاملة، لكن واجهة التطبيق دي (الـ HTML بتاعها)
        // موجودة أصلاً في الـ DOM من أول تحميل الصفحة (initApp() بس بتأجّل
        // تشغيل الـ JS بتاعها لحد ما initOnboarding() تخلص - شوف app.js) -
        // فلو طولها أكبر من الشاشة، <body> بيفضل قابل للسكرول فعليًا حتى لو
        // المستخدم شايف شاشة ترحيب "ثابتة" بصريًا فوقها، وده اللي كان بيسبب
        // علامة سكرول تطلع وتنزل من غير أي سبب ظاهر. قفل السكرول هنا بالكامل
        // طول ما شاشة الترحيب ظاهرة بيمنع ده تماماً - بيتشال في finish() تحت
        // أول ما الشاشة تقفل فعلياً
        document.body.classList.add('onb-scroll-lock');

        const glow1 = document.getElementById('onbGlow1');
        const glow2 = document.getElementById('onbGlow2');
        const nextBtn = document.getElementById('onbNextBtn');
        const nextBtnText = document.getElementById('onbNextBtnText');
        const skipBtn = document.getElementById('onbSkipBtn');
        const bullets = Array.from(overlay.querySelectorAll('.onb-bullet'));
        const slides = Array.from(overlay.querySelectorAll('.swiper-slide'));

        // عناصر "صفحة الدخول" الكاملة (#onbAuthFormDock) اللي بتفتح فوق
        // كروت الترحيب لما المستخدم يضغط "إنشاء حساب"/"تسجيل الدخول" من
        // آخر سلايد - عنصر مستقل بملء الشاشة، مش جزء من السلايد نفسه
        // (شوف index.html لتفاصيل الـ HTML)
        const authFormDock = document.getElementById('onbAuthFormDock');
        const authFormSlot = document.getElementById('onbAuthFormSlot');
        const authPageTitle = document.getElementById('onbAuthPageTitle');
        const authBackBtn = document.getElementById('onbAuthBackBtn');

        // عناصر صفحة "الموقع برّه النطاق" (#onbLocationRejectedDock) -
        // بتظهر بدل فورم التسجيل لو فحص الموقع قبل التسجيل رفض (شوف
        // evaluateSignupLocationGate فوق و onSignupClick تحت)
        const signupBtn = document.getElementById('onbSignupBtn');
        const loginBtn = document.getElementById('onbLoginBtn');
        const locationRejectedDock = document.getElementById('onbLocationRejectedDock');
        const locationRejectedMessage = document.getElementById('onbLocationRejectedMessage');
        const locationRejectedBackBtn = document.getElementById('onbLocationRejectedBackBtn');
        const locationRetryBtn = document.getElementById('onbLocationRetryBtn');
        const guestBrowseBtn = document.getElementById('onbGuestBrowseBtn');

        // زرار "تصفح كزائر" التاني - ده على شاشة الاختيار الأساسية نفسها
        // (#onbAuthChoiceView)، ظاهر للكل من غير فحص موقع أصلاً (حتى لو
        // هو فعلاً جوه نزلة عبيد وحابب يجرّب التطبيق الأول قبل ما يعمل
        // حساب). شكله متعمّد يبقى صغير/ثانوي (نص تحت الزرارين، مش زرار
        // كامل زي onbGuestBrowseBtn) عشان يفضل خيار جانبي واضح مش بديل
        // بصري عن التسجيل - راجع index.html للتنسيق
        const choiceGuestBrowseBtn = document.getElementById('onbChoiceGuestBrowseBtn');

        // مدة أنيميشن فتح/قفل صفحة الدخول بالمللي ثانية - لازم تتطابق مع
        // transition-duration بتاعة ".onb-auth-page" في css/onboarding.css
        // (شوف returnToChoiceView تحت ليه محتاجينها بالظبط)
        const AUTH_PAGE_TRANSITION_MS = 380;

        // 'signup' أو 'login' حسب آخر زرار ضغطه المستخدم من شاشة
        // الاختيار - بنستخدمها لما ننجح فعلاً في تسجيل الدخول عشان
        // نعرف نرجّع القيمة الصح من initOnboarding()
        let pendingAuthIntent = null;

        // كأس البطولة الحقيقي (Lottie) - بيتحمّل من غير ما يشتغل
        // (autoplay: false)، وبيتشغّل مرة واحدة بس لحظة الوصول لآخر
        // سلايد (زي الكونفيتي بالظبط - شوف trophyCelebrated تحت)
        const trophyLottieContainer = document.getElementById('onbTrophyLottie');
        const trophyFallbackSvg = overlay.querySelector('.onb-trophy-fallback');
        const trophyAnim = initTrophyLottie(trophyLottieContainer, trophyFallbackSvg);

        // شخصية الماشي الحقيقي (Lottie) - سلايد 2 بس، بيشتغل لوب
        // مستمر من لحظة ظهوره (autoplay: true)، عكس الكأس اللي بيتفعّل
        // مرة واحدة بس لحظة معينة
        const walkLottieContainer = document.getElementById('onbWalkLottie');
        const walkFallbackSvg = overlay.querySelector('.onb-walk-fallback');
        initWalkLottie(walkLottieContainer, walkFallbackSvg);

        // علامات الاستفهام المتحركة (Lottie) - سلايد 3 بس، بيشتغل لوب
        // مستمر من لحظة ظهوره (autoplay: true) زي شخصية الماشي بالظبط
        const quizLottieContainer = document.getElementById('onbQuizLottie');
        const quizFallbackSvg = overlay.querySelector('.onb-quiz-fallback');
        initQuizLottie(quizLottieContainer, quizFallbackSvg);

        // الدبوس/الموقع المتحرك (Lottie) - سلايد 4 بس، بيشتغل لوب
        // مستمر من لحظة ظهوره (autoplay: true) بنفس منطق باقي أيقونات
        // السلايدات المتحركة
        const locationLottieContainer = document.getElementById('onbLocationLottie');
        const locationFallbackSvg = overlay.querySelector('.onb-location-fallback');
        initLocationLottie(locationLottieContainer, locationFallbackSvg);

        // الكأس/المنصة المتحركة (Lottie) - سلايد 5 بس، بيشتغل لوب
        // مستمر من لحظة ظهوره (autoplay: true) بنفس منطق باقي أيقونات
        // السلايدات المتحركة
        const rankLottieContainer = document.getElementById('onbRankLottie');
        const rankFallbackSvg = overlay.querySelector('.onb-rank-fallback');
        initRankLottie(rankLottieContainer, rankFallbackSvg);

        // عملة النقاط المتحركة (Lottie) - سلايد 6 بس، بيشتغل لوب
        // مستمر من لحظة ظهوره (autoplay: true) بنفس منطق باقي أيقونات
        // السلايدات المتحركة
        const pointsLottieContainer = document.getElementById('onbPointsLottie');
        const pointsFallbackSvg = overlay.querySelector('.onb-points-fallback');
        initPointsLottie(pointsLottieContainer, pointsFallbackSvg);

        // أيقونة الكتابة المتحركة (Lottie) - سلايد 8 بس، بيشتغل لوب
        // مستمر من لحظة ظهوره (autoplay: true) بنفس منطق باقي أيقونات
        // السلايدات المتحركة
        const writingLottieContainer = document.getElementById('onbWritingLottie');
        const writingFallbackSvg = overlay.querySelector('.onb-writing-fallback');
        initWritingLottie(writingLottieContainer, writingFallbackSvg);

        let trophyCelebrated = false; // نضمن إن الكونفيتي يشتغل مرة واحدة بس

        const swiper = new Swiper(overlay.querySelector('.onbSwiper'), {
            effect: 'cards',
            grabCursor: true,
            cardsEffect: {
                perSlideOffset: 12,
                perSlideRotate: 4,
                rotate: true,
                slideShadows: true,
            },
            speed: 450,
            resistanceRatio: 0.85,
            on: {
                slideChange() {
                    updateSlideExperience(this.realIndex);
                    playHapticTick();
                },
            },
        });

        function updateSlideExperience(index) {
            const activeSlide = slides[index];
            if (!activeSlide) return;

            const c1 = activeSlide.getAttribute('data-glow1') || '#D4AF37';
            const c2 = activeSlide.getAttribute('data-glow2') || '#B8942A';
            const accent = activeSlide.getAttribute('data-accent') || '#D4AF37';

            if (glow1) glow1.style.backgroundColor = c1;
            if (glow2) glow2.style.backgroundColor = c2;
            overlay.style.setProperty('--onb-active-accent', accent);

            bullets.forEach((b, i) => b.classList.toggle('onb-bullet-active', i === index));

            const isLast = index === TOTAL_SLIDES - 1;
            nextBtnText.textContent = isLast ? 'يلا بينا' : 'التالي';
            nextBtn.classList.toggle('opacity-0', isLast);
            nextBtn.classList.toggle('pointer-events-none', isLast);

            if (isLast && !trophyCelebrated) {
                trophyCelebrated = true;
                if (trophyAnim) {
                    try {
                        trophyAnim.goToAndStop(0, true);
                        trophyAnim.play();
                    } catch (err) {
                        // مايهمناش لو الأنيميشن رفض يشتغل هنا - الكأس
                        // الاحتياطي بيبان تلقائياً لو التهيئة الأولانية
                        // فشلت أصلاً في initTrophyLottie()
                    }
                }
                setTimeout(burstGoldConfetti, 250); // بعد لحظة بسيطة من ظهور الكأس
            }
        }

        bullets.forEach((bullet) => {
            bullet.addEventListener('click', () => {
                swiper.slideTo(parseInt(bullet.getAttribute('data-index'), 10));
            });
        });

        nextBtn.addEventListener('click', () => {
            if (swiper.realIndex < TOTAL_SLIDES - 1) swiper.slideNext();
        });

        skipBtn.addEventListener('click', () => {
            swiper.slideTo(TOTAL_SLIDES - 1);
            playHapticTick();
        });

        function finish(authIntent) {
            document.removeEventListener('auth:signed-in', handleAuthSuccessDuringOnboarding);
            markOnboardingSeen();
            // (إصلاح): نطفّي الفلاج هنا - من اللحظة دي showAuthGate() تقدر
            // تشتغل عادي (لتسجيل خروج حقيقي لاحق مثلاً) من غير ما تتصادم
            // مع رحلة سلايدات خلصت أصلاً
            firstRunOnboardingActive = false;
            overlay.classList.add('hidden');
            // (إصلاح - باج حقيقي): لازم نضيف الكلاس ده على <body> عشان
            // يلغي قاعدة "!important" المحقونة في index.html (شوف تعليقها
            // هناك) - من غيره، كلاس "hidden" فوق ده مش هيبان بصريًا خالص
            // لحد ما المستخدم يعمل Refresh فعلي للصفحة (وده بالظبط اللي
            // كان بيسبب "تصفح كزائر ما بيدخلش غير بعد الريفريش")
            document.body.classList.add('onb-gate-dismissed');
            // بنفك قفل السكرول (onb-scroll-lock) بمجرد ما الشاشة تقفل فعلياً
            // - من هنا لحد ما التطبيق نفسه (اللي كان مستني وراها) ياخد التحكم
            document.body.classList.remove('onb-scroll-lock');
            swiper.destroy(true, true);
            if (trophyAnim) trophyAnim.destroy();
            resolve(authIntent);
        }

        /** بتفتح "صفحة الدخول" الكاملة (#onbAuthFormDock) بأنيميشن انزلاق/
         *  تلاشي فوق كروت السلايدات مباشرة (بدل ما تقفل شاشة الترحيب
         *  وتفتح واجهة تانية، وبدل ما تفضل جزء صغير جوه كارت السلايد) -
         *  بتحدّث العنوان ديناميكياً حسب النية ("إنشاء حساب جديد" أو
         *  "تسجيل الدخول")، وبتنقل عنصر #authModal الحقيقي بتاع js/auth.js
         *  جوه #onbAuthFormSlot وتشيل شكله كمودال منبثق (شوف showAuthModal
         *  في auth.js) */
        function revealAuthForm(intent) {
            pendingAuthIntent = intent;

            if (authPageTitle) {
                authPageTitle.textContent = intent === 'signup' ? 'إنشاء حساب جديد' : 'تسجيل الدخول';
            }

            authFormDock.classList.remove('hidden');

            // بنستنى فريمين (مش فريم واحد بس - بعض المتصفحات بتحتاج
            // فريمين فعلاً عشان تسجّل حالة البداية بشكل مضمون) قبل ما
            // نضيف كلاس الحركة، وإلا المتصفح هيدمج إزالة "hidden" وإضافة
            // "onb-auth-page-visible" في نفس اللحظة ومش هيعمل transition
            // خالص (هيقفز على طول للحالة النهائية من غير أي حركة تُذكر)
            requestAnimationFrame(() => {
                requestAnimationFrame(() => {
                    authFormDock.classList.add('onb-auth-page-visible');
                });
            });

            showAuthModal(intent === 'signup' ? 'signup' : 'signin', { dockTarget: authFormSlot });
        }

        /** رجوع لشاشة اختيار "إنشاء حساب / تسجيل دخول" - بيرجّع
         *  #authModal لمكانه الأصلي كمودال منبثق (جاهز لأي استخدام
         *  لاحق)، وبيقفل "صفحة الدخول" الكاملة بنفس أنيميشن الانزلاق/
         *  التلاشي بالعكس. بنستنى مدة الحركة (AUTH_PAGE_TRANSITION_MS)
         *  تخلّص فعلاً قبل ما نضيف "hidden" (display: none)، وإلا الصفحة
         *  هتختفي فجأة نص الحركة بدل ما تنزلق لتحت وتتلاشى بسلاسة */
        function returnToChoiceView() {
            hideAuthModal();
            authFormDock.classList.remove('onb-auth-page-visible');
            window.setTimeout(() => {
                authFormDock.classList.add('hidden');
            }, AUTH_PAGE_TRANSITION_MS);
            pendingAuthIntent = null;
        }

        /** بتتفعّل بس لما فورم الدخول يكون فعلاً ظاهر جوه شاشة الترحيب
         *  (يعني احنا في وضع "مدموج") - أي حدث "auth:signed-in" قبل
         *  كده (زي جلسة محفوظة لمستخدم تاني، نظرياً مستحيل هنا لأن
         *  initOnboarding() بترجع فوراً لأي مستخدم شاف الترحيب قبل
         *  كده) أو بعد ما الترحيب يكون خلص بيتجاهل تماماً */
        function handleAuthSuccessDuringOnboarding() {
            if (authFormDock.classList.contains('hidden')) return;
            finish(pendingAuthIntent || 'login');
        }

        document.addEventListener('auth:signed-in', handleAuthSuccessDuringOnboarding);

        /** إظهار صفحة "الموقع برّه النطاق" (#onbLocationRejectedDock)
         *  بنفس أنيميشن انزلاق/تلاشي #onbAuthFormDock بالظبط (نفس كلاس
         *  onb-auth-page-visible - شوف تعليق revealAuthForm فوق للسبب) */
        function showLocationRejected(message) {
            if (locationRejectedMessage) {
                locationRejectedMessage.textContent = message;
            }

            locationRejectedDock.classList.remove('hidden');
            requestAnimationFrame(() => {
                requestAnimationFrame(() => {
                    locationRejectedDock.classList.add('onb-auth-page-visible');
                });
            });
        }

        function hideLocationRejected() {
            locationRejectedDock.classList.remove('onb-auth-page-visible');
            window.setTimeout(() => {
                locationRejectedDock.classList.add('hidden');
            }, AUTH_PAGE_TRANSITION_MS);
        }

        /** معالج زرار "إنشاء حساب جديد" - بيفحص الموقع الجغرافي الأول
         *  (evaluateSignupLocationGate فوق) قبل ما يفتح فورم التسجيل
         *  خالص. فورم "تسجيل الدخول" (onLoginClick) مش متأثر - عضو
         *  موجود بالفعل ومعاه استثناء يدوي ممكن يكون مسافر مؤقتاً */
        async function onSignupClick() {
            playHapticTick(560, 'triangle', 0.05);

            const originalLabel = signupBtn.innerHTML;
            signupBtn.disabled = true;
            signupBtn.setAttribute('aria-busy', 'true');
            signupBtn.innerHTML = '<span>بنتحقق من موقعك...</span>';

            const result = await evaluateSignupLocationGate();

            signupBtn.disabled = false;
            signupBtn.removeAttribute('aria-busy');
            signupBtn.innerHTML = originalLabel;

            if (result.allowed) {
                revealAuthForm('signup');
            } else {
                showLocationRejected(result.message);
            }
        }

        signupBtn.addEventListener('click', onSignupClick);

        loginBtn.addEventListener('click', () => {
            playHapticTick(560, 'triangle', 0.05);
            revealAuthForm('login');
        });

        locationRejectedBackBtn.addEventListener('click', () => {
            playHapticTick();
            hideLocationRejected();
        });

        locationRetryBtn.addEventListener('click', () => {
            hideLocationRejected();
            window.setTimeout(onSignupClick, AUTH_PAGE_TRANSITION_MS);
        });

        // "تصفح كزائر": بيكمّل استخدام التطبيق من غير حساب خالص. بيرجّع
        // 'guest-browse' كـ authIntent من initOnboarding() نفسها - app.js
        // لازم يتعامل معاها كحالة خاصة (مش زي 'signup'/'login' العاديين)
        // ومايفتحش showAuthGate() تاني بعدها (شوف التعليق في app.js)
        guestBrowseBtn.addEventListener('click', () => {
            playHapticTick();
            // (إصلاح): تسجيل القرار في localStorage *قبل* finish() -
            // عشان لو المستخدم عمل Refresh بعدها بأي لحظة، checkExistingSession()
            // (js/auth.js) تعرف تسيبه في وضع الزائر بدل ما ترجّعه لصفحة
            // التسجيل من جديد (شوف تعليق GUEST_MODE_STORAGE_KEY في auth.js)
            markGuestModeActive();
            finish('guest-browse');
        });

        // نفس بالظبط معالج guestBrowseBtn فوق (نفس markGuestModeActive +
        // finish('guest-browse')) - عمداً من غير أي فحص موقع جغرافي هنا،
        // لأن الهدف بالظبط إن أي حد (حتى لو جوه نزلة عبيد) يقدر يجرّب
        // التطبيق الأول من غير حساب لو حب، مش بس اللي اترفض تسجيله.
        // الأمان (منع الغرباء من عمل حساب) هيفضل شغال زي ما هو بالظبط
        // لاحقًا وقت الضغط الفعلي على "إنشاء حساب" (evaluateSignupLocationGate)
        // - مش هنا، فمفيش داعي لأي فحص إضافي في المسار ده
        if (choiceGuestBrowseBtn) {
            choiceGuestBrowseBtn.addEventListener('click', () => {
                playHapticTick();
                markGuestModeActive();
                finish('guest-browse');
            });
        }

        authBackBtn.addEventListener('click', () => {
            playHapticTick();
            returnToChoiceView();
        });

        updateSlideExperience(0);
    });
}

/* ------------------------------------------------------------------
   4) بوابة الدخول بعد تسجيل الخروج (Logout Gate)
   ------------------------------------------------------------------
   بتتنادى من js/auth.js (signOut) بدل ما نفتح authModal كمودال منبثق
   فوق التطبيق (Blur خلفه). بتعرض نفس "شاشة اختيار الدخول" (كأس +
   زرارين إنشاء حساب/تسجيل دخول) وصفحة الدخول الكاملة (#onbAuthFormDock)
   اللي المستخدم شافها بالظبط أول مرة في آخر سلايد ترحيب - لكن من غير
   إعادة عرض الستة سلايدات الأولى ولا تشغيل Swiper خالص (بنخفي كل
   السلايدات ما عدا سلايد الاختيار الأخيرة بـ display:none مباشرة،
   ومنخفيش/بنعطّل عناصر التنقل زي التخطي والنقاط وزرار التالي لأنها
   مالهاش لازمة هنا أصلاً).

   بعكس initOnboarding()، الدالة دي ممكن تتنادى أكتر من مرة في نفس
   الجلسة (كل ما المستخدم يسجل خروج) - فلازم نضمن إننا بنرجّع كل حاجة
   (السلايدات، صفحة الدخول) لحالتها الافتراضية في cleanup() تحت، جاهزة
   لأي استدعاء تاني بعد كده من غير أي أثر من المرة اللي فاتت.
   ------------------------------------------------------------------
   بارامتر اختياري: initialIntent
   ------------------------------------------------------------------
   لو اتبعت 'login'، بنفتح فورم "تسجيل الدخول" (#onbAuthFormDock)
   على طول بعد ما الشاشة تتجهز، من غير ما نستنى المستخدم يضغط زرار
   "تسجيل الدخول" في شاشة الاختيار الأولى - نفس اللي js/guest-banner.js
   محتاجه بالظبط (زرار البانر بيفتح تسجيل دخول بس، مش اختيار، لإن
   إنشاء حساب جديد ممنوع أصلاً لغير سكان القرية). من غير الباراميتر
   ده (أو لو اتبعت أي قيمة تانية غير 'login')، السلوك زي ما هو بالظبط:
   بتظهر شاشة الاختيار (إنشاء حساب / تسجيل دخول) الأول.
   ------------------------------------------------------------------ */
export function showAuthGate(initialIntent = null) {
    // (إصلاح - باج حقيقي): لو initOnboarding() (رحلة السلايدات الأولى)
    // شغالة فعليًا دلوقتي، ما نعملش حاجة خالص وترجع فورًا. initOnboarding()
    // نفسها هي اللي هتعرض نفس شاشة الاختيار/تسجيل الدخول دي لأي زائر أول
    // مرة أصلاً - فمفيش داعي لـ showAuthGate() تتدخل معاها في نفس الوقت
    // وتزاحمها على نفس عناصر الـ DOM (شوف تعليق firstRunOnboardingActive
    // فوق للتفاصيل الكاملة عن الباج اللي ده بيصلحه)
    if (firstRunOnboardingActive) return;

    const overlay = document.getElementById('onboardingOverlay');
    if (!overlay) {
        // احتياطي: لو العنصر مش موجود لأي سبب، نرجع لمودال تسجيل الدخول
        // المنبثق العادي بدل ما نسيب المستخدم من غير أي واجهة دخول خالص
        showAuthModal();
        return;
    }

    // لو الشاشة دي شغالة بالفعل (مثلاً ضغطتين "تسجيل خروج" سريعتين)
    // منكررش التهيئة تاني
    if (overlay.classList.contains('onb-gate-active')) return;
    overlay.classList.add('onb-gate-active');
    overlay.classList.remove('hidden');
    // نفس قفل السكرول المطبّق في initOnboarding() فوق، ولنفس السبب
    // بالظبط - الشاشة دي كمان "fixed" فوق واجهة تطبيق موجودة بالكامل
    // في الـ DOM وراها
    document.body.classList.add('onb-scroll-lock');

    const skipBtn = document.getElementById('onbSkipBtn');
    const footer = overlay.querySelector('footer');
    const slides = Array.from(overlay.querySelectorAll('.swiper-slide'));
    const lastSlide = slides[slides.length - 1];

    // نخفي كل السلايدات ما عدا سلايد الاختيار الأخيرة (نفس الحالة اللي
    // كان المستخدم بيوصلها بعد ما يخلّص كل السلايدات أول مرة)، ونخفي
    // زرار التخطي والتذييل (النقاط + زرار التالي) لأننا مش بنعرض رحلة
    // ترحيب فعلية هنا، بس نفس شاشة الاختيار وصفحة الدخول بس
    slides.forEach((slide) => {
        slide.style.display = slide === lastSlide ? '' : 'none';
    });
    if (skipBtn) skipBtn.style.display = 'none';
    if (footer) footer.style.display = 'none';

    // (إصلاح - باج حقيقي): initOnboarding() بتلوّن الأضواء الخلفية
    // (#onbGlow1/#onbGlow2) عن طريق updateSlideExperience() اللي بتتنادى
    // من حدث "slideChange" بتاع Swiper الحقيقي. هنا في showAuthGate()
    // مفيش Swiper شغال أصلاً (بس تبديل display يدوي فوق) فـ
    // updateSlideExperience() ما كانتش بتتنادى خالص - يعني الأضواء
    // كانت فاضلة من غير أي لون (مفيش قيمة افتراضية في الـ CSS)، فشاشة
    // الاختيار كانت بتبان بخلفية سودة صلبة رغم إنها نفس العنصر بالظبط
    // بتاع أول مرة (نفس الكروت والزراير) - ده اللي كان بيدّي إحساس
    // "صفحة تانية طبق الأصل بس خلفيتها مختلفة". دلوقتي بنلوّن الأضواء
    // يدويًا من بيانات نفس السلايد الأخيرة (data-glow1/data-glow2) قبل
    // ما نوريها، بنفس القيم اللي updateSlideExperience() كانت هتحطها
    // بالظبط لو كنا جايين من رحلة سلايدات حقيقية
    const glow1 = document.getElementById('onbGlow1');
    const glow2 = document.getElementById('onbGlow2');
    if (lastSlide) {
        const c1 = lastSlide.getAttribute('data-glow1') || '#D4AF37';
        const c2 = lastSlide.getAttribute('data-glow2') || '#B8942A';
        const accent = lastSlide.getAttribute('data-accent') || '#D4AF37';
        if (glow1) glow1.style.backgroundColor = c1;
        if (glow2) glow2.style.backgroundColor = c2;
        overlay.style.setProperty('--onb-active-accent', accent);
    }

    // كأس البطولة - نفس أنيميشن أول مرة بالظبط
    const trophyLottieContainer = document.getElementById('onbTrophyLottie');
    const trophyFallbackSvg = overlay.querySelector('.onb-trophy-fallback');
    const trophyAnim = initTrophyLottie(trophyLottieContainer, trophyFallbackSvg);
    if (trophyAnim) {
        try {
            trophyAnim.goToAndStop(0, true);
            trophyAnim.play();
        } catch (err) {
            // مش مهم لو فشل هنا - الكأس الاحتياطي بيبان تلقائياً
        }
    }
    setTimeout(burstGoldConfetti, 250);

    const authFormDock = document.getElementById('onbAuthFormDock');
    const authFormSlot = document.getElementById('onbAuthFormSlot');
    const authPageTitle = document.getElementById('onbAuthPageTitle');
    const authBackBtn = document.getElementById('onbAuthBackBtn');
    const signupBtn = document.getElementById('onbSignupBtn');
    const loginBtn = document.getElementById('onbLoginBtn');

    // عناصر صفحة "الموقع برّه النطاق" - نفس المنطق المستخدم في
    // initOnboarding() فوق بالظبط (شوف تعليقها هناك للتفاصيل)
    const locationRejectedDock = document.getElementById('onbLocationRejectedDock');
    const locationRejectedMessage = document.getElementById('onbLocationRejectedMessage');
    const locationRejectedBackBtn = document.getElementById('onbLocationRejectedBackBtn');
    const locationRetryBtn = document.getElementById('onbLocationRetryBtn');
    const guestBrowseBtn = document.getElementById('onbGuestBrowseBtn');

    // (إصلاح - باج حقيقي: "وضع الزائر مش بيستجيب تاني"): showAuthGate()
    // بترسم وتعرض سلايد الاختيار الأخيرة (#onbAuthChoiceView) - نفس
    // السلايد اللي فيها زرار "تصفح كزائر الأول من غير حساب"
    // (#onbChoiceGuestBrowseBtn، شوف initOnboarding() فوق). قبل الإصلاح
    // ده، الدالة كانت بتجيب وتربط بس onbGuestBrowseBtn (زرار صفحة
    // "الموقع برّه النطاق" التانية تمامًا) وتتجاهل onbChoiceGuestBrowseBtn
    // خالص - فأي زائر يعمل: تصفح كزائر (اشتغل من initOnboarding) ← يضغط
    // "سجّل دلوقتي" (showAuthGate() بتفتح نفس شاشة الاختيار) ← يضغط
    // "تصفح كزائر" تاني - كانت الضغطة دي مالهاش أي مستمع click خالص،
    // فتبان "مش بتستجيب". نفس معالج onGuestBrowseClick تحت بالظبط.
    const choiceGuestBrowseBtn = document.getElementById('onbChoiceGuestBrowseBtn');

    // مدة أنيميشن فتح/قفل صفحة الدخول - لازم تتطابق مع transition-duration
    // بتاعة ".onb-auth-page" في css/onboarding.css (نفس القيمة المستخدمة
    // في initOnboarding() فوق)
    const AUTH_PAGE_TRANSITION_MS = 380;

    // احتياطي دفاعي: نضمن إن صفحة الدخول الكاملة (وصفحة الرفض) تبدأ
    // مقفولة دايماً حتى لو فضل أثر (class) من استدعاء سابق لأي سبب
    // غير متوقع
    authFormDock.classList.add('hidden');
    authFormDock.classList.remove('onb-auth-page-visible');
    locationRejectedDock.classList.add('hidden');
    locationRejectedDock.classList.remove('onb-auth-page-visible');

    function revealAuthForm(intent) {
        if (authPageTitle) {
            authPageTitle.textContent = intent === 'signup' ? 'إنشاء حساب جديد' : 'تسجيل الدخول';
        }

        authFormDock.classList.remove('hidden');
        // بنستنى فريمين قبل ما نضيف كلاس الحركة، زي نفس السبب المشروح
        // في revealAuthForm بتاعة initOnboarding() فوق بالظبط
        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                authFormDock.classList.add('onb-auth-page-visible');
            });
        });

        showAuthModal(intent === 'signup' ? 'signup' : 'signin', { dockTarget: authFormSlot });
    }

    function returnToChoiceView() {
        hideAuthModal();
        authFormDock.classList.remove('onb-auth-page-visible');
        window.setTimeout(() => {
            authFormDock.classList.add('hidden');
        }, AUTH_PAGE_TRANSITION_MS);
    }

    function showLocationRejected(message) {
        if (locationRejectedMessage) {
            locationRejectedMessage.textContent = message;
        }

        locationRejectedDock.classList.remove('hidden');
        requestAnimationFrame(() => {
            requestAnimationFrame(() => {
                locationRejectedDock.classList.add('onb-auth-page-visible');
            });
        });
    }

    function hideLocationRejected() {
        locationRejectedDock.classList.remove('onb-auth-page-visible');
        window.setTimeout(() => {
            locationRejectedDock.classList.add('hidden');
        }, AUTH_PAGE_TRANSITION_MS);
    }

    /** بيفحص الموقع الجغرافي الأول قبل ما يفتح فورم "إنشاء حساب جديد" -
     *  نفس منطق onSignupClick بتاعة initOnboarding() فوق بالظبط */
    async function onSignupClick() {
        playHapticTick(560, 'triangle', 0.05);

        const originalLabel = signupBtn.innerHTML;
        signupBtn.disabled = true;
        signupBtn.setAttribute('aria-busy', 'true');
        signupBtn.innerHTML = '<span>بنتحقق من موقعك...</span>';

        const result = await evaluateSignupLocationGate();

        signupBtn.disabled = false;
        signupBtn.removeAttribute('aria-busy');
        signupBtn.innerHTML = originalLabel;

        if (result.allowed) {
            revealAuthForm('signup');
        } else {
            showLocationRejected(result.message);
        }
    }

    function onLoginClick() {
        playHapticTick(560, 'triangle', 0.05);
        revealAuthForm('login');
    }

    function onBackClick() {
        playHapticTick();
        returnToChoiceView();
    }

    function onLocationRejectedBackClick() {
        playHapticTick();
        hideLocationRejected();
    }

    function onLocationRetryClick() {
        hideLocationRejected();
        window.setTimeout(onSignupClick, AUTH_PAGE_TRANSITION_MS);
    }

    /** "تصفح كزائر": بيقفل بوابة الدخول ويكمّل استخدام التطبيق من غير
     *  حساب. بعكس initOnboarding() (اللي بترجع Promise)، الدالة دي
     *  بتتنادى مباشرة من auth.js (signOut) من غير أي قيمة راجعة، فبنعلن
     *  عن دخول وضع الزائر بحدث عام على document بدل كده - app.js بيسمعه
     *  في initSharedUIBridge() وينادي initGeofencingGuard(null) (نفس
     *  المسار الاحترازي الموجود بالفعل، شوف geofence.js) */
    function onGuestBrowseClick() {
        playHapticTick();
        // (إصلاح): نفس تسجيل القرار المطبّق في initOnboarding() فوق -
        // عشان استمرار وضع الزائر يشتغل بنفس الطريقة سواء المستخدم اختاره
        // أول مرة من شاشات الترحيب أو من هنا بعد تسجيل الخروج
        markGuestModeActive();
        cleanup();
        document.dispatchEvent(new CustomEvent('app:enter-guest-browsing'));
    }

    function cleanup() {
        document.removeEventListener('auth:signed-in', handleAuthSuccess);
        signupBtn.removeEventListener('click', onSignupClick);
        loginBtn.removeEventListener('click', onLoginClick);
        authBackBtn.removeEventListener('click', onBackClick);
        locationRejectedBackBtn.removeEventListener('click', onLocationRejectedBackClick);
        locationRetryBtn.removeEventListener('click', onLocationRetryClick);
        guestBrowseBtn.removeEventListener('click', onGuestBrowseClick);
        if (choiceGuestBrowseBtn) choiceGuestBrowseBtn.removeEventListener('click', onGuestBrowseClick);

        overlay.classList.add('hidden');
        overlay.classList.remove('onb-gate-active');
        document.body.classList.remove('onb-scroll-lock');
        // (إصلاح - باج حقيقي): نفس الإصلاح المطبّق في finish() بتاعة
        // initOnboarding() فوق - من غيره، قاعدة "!important" المحقونة في
        // index.html بتفضل تغلب كلاس "hidden" فوق ده، فالشاشة كانت بتفضل
        // ظاهرة بصريًا رغم إن الكود بيقفلها فعلاً، لحد ما يحصل Refresh
        document.body.classList.add('onb-gate-dismissed');

        // نرجّع كل حاجة لحالتها الافتراضية استعداداً لأي تسجيل خروج تاني
        // في نفس الجلسة
        slides.forEach((slide) => slide.style.removeProperty('display'));
        if (skipBtn) skipBtn.style.removeProperty('display');
        if (footer) footer.style.removeProperty('display');
        authFormDock.classList.add('hidden');
        authFormDock.classList.remove('onb-auth-page-visible');
        locationRejectedDock.classList.add('hidden');
        locationRejectedDock.classList.remove('onb-auth-page-visible');
        if (trophyAnim) trophyAnim.destroy();
    }

    function handleAuthSuccess() {
        cleanup();
    }

    document.addEventListener('auth:signed-in', handleAuthSuccess);
    signupBtn.addEventListener('click', onSignupClick);
    loginBtn.addEventListener('click', onLoginClick);
    authBackBtn.addEventListener('click', onBackClick);
    locationRejectedBackBtn.addEventListener('click', onLocationRejectedBackClick);
    locationRetryBtn.addEventListener('click', onLocationRetryClick);
    guestBrowseBtn.addEventListener('click', onGuestBrowseClick);
    if (choiceGuestBrowseBtn) choiceGuestBrowseBtn.addEventListener('click', onGuestBrowseClick);

    // لو الطلب جاي بنية "تسجيل الدخول" مباشرة (initialIntent === 'login')
    // زي js/guest-banner.js بالظبط، نفتح فورم الدخول فورًا من غير ما
    // نستنى ضغطة على زرار شاشة الاختيار - بنفس مسار onLoginClick()
    // العادي تمامًا (haptic + revealAuthForm) عشان مفيش أي فرق سلوك
    // غير نقطة البداية بس
    if (initialIntent === 'login') {
        onLoginClick();
    }
}